package com.mo.economy_system.target.forge1201.network;import static org.junit.jupiter.api.Assertions.*;import com.mo.economy_system.common.network.*;import io.netty.buffer.Unpooled;import java.util.UUID;import net.minecraft.network.FriendlyByteBuf;import org.junit.jupiter.api.Test;
class Forge1201DeliverDemandOrderProtocolTest{@Test void codecRoundTripsAt14(){var m=new DeliverDemandOrderMessage(UUID.randomUUID());var b=new FriendlyByteBuf(Unpooled.buffer());Forge1201DeliverDemandOrderCodec.encode(m,b);assertEquals(m,Forge1201DeliverDemandOrderCodec.decode(b));assertEquals(14,EconomyMessages.DELIVER_DEMAND_ORDER.discriminator());}@Test void nullRejected(){assertThrows(NullPointerException.class,()->new DeliverDemandOrderMessage(null));}}
